    84→    public void processMessages() throws QueueException {
    85→        List<EventMessage> eventMessages = eventSubscriberQueue.retrieveEvents();
    86→        for (EventMessage message : eventMessages) {
    87→            try {
    88→                EventType eventType = EventType.byType(message.getEvent().getEventType());
    89→
    90→                logger.info("Retrieved event queue message with id [{}] for resource external id [{}]",
    91→                        message.getQueueMessage().getMessageId(), message.getEvent().getResourceExternalId());
    92→
    93→                switch (eventType) {
    94→                    case DISPUTE_CREATED:
    95→                        handleDisputeCreatedMessage(message.getEvent());
    96→                        break;
    97→                    case DISPUTE_EVIDENCE_SUBMITTED:
    98→                        handleDisputeEvidenceSubmittedMessage(message.getEvent());
    99→                        break;
   100→                    case DISPUTE_LOST:
   101→                        handleDisputeLostMessage(message.getEvent());
   102→                        break;
   103→                    case DISPUTE_WON:
   104→                        handleDisputeWonMessage(message.getEvent());
   105→                        break;
   106→                    default:
   107→                        logger.info("Unknown event type: {}", message.getEvent().getEventType());
   108→                }
   109→
   110→                eventSubscriberQueue.markMessageAsProcessed(message.getQueueMessage());
   111→            } catch (Exception e) {
   112→                Sentry.captureException(e);
   113→                logger.warn("An error occurred handling the event message",
   114→                        kv("sqs_message_id", message.getQueueMessage().getMessageId()),
   115→                        kv("resource_external_id", message.getEvent().getResourceExternalId()),
   116→                        kv("error", e.getMessage())
   117→                );
   118→            }
   119→        }
   120→    }
